import{_ as t,o,c as a,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const d=JSON.parse('{"title":"Troubleshooting: Image & Video Generation","description":"Fix issues with Veo loop generation and Imagen generation.","frontmatter":{"title":"Troubleshooting: Image & Video Generation","description":"Fix issues with Veo loop generation and Imagen generation."},"headers":[],"relativePath":"support/troubleshooting_visuals.md","filePath":"support/troubleshooting_visuals.md"}'),i={name:"support/troubleshooting_visuals.md"};function n(r,e,l,u,g,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting-image-video-generation" tabindex="-1">Troubleshooting: Image &amp; Video Generation <a class="header-anchor" href="#troubleshooting-image-video-generation" aria-label="Permalink to &quot;Troubleshooting: Image &amp; Video Generation&quot;">​</a></h1><h2 id="_1-safety-policy-violations" tabindex="-1">1. Safety Policy Violations <a class="header-anchor" href="#_1-safety-policy-violations" aria-label="Permalink to &quot;1. Safety Policy Violations&quot;">​</a></h2><p><strong>Symptom:</strong> The visual generation fails instantly with a red &quot;Safety Policy Violation&quot; error. <strong>Cause:</strong> The prompt sent to Google&#39;s Vertex AI contained words flagged by their mandatory safety filters (hate speech, violence, explicit content, etc.). <strong>Solution:</strong> Edit the visual prompt in the Visual Stage to remove or soften any potentially sensitive terms.</p><h2 id="_2-vertex-ai-timeouts" tabindex="-1">2. Vertex AI Timeouts <a class="header-anchor" href="#_2-vertex-ai-timeouts" aria-label="Permalink to &quot;2. Vertex AI Timeouts&quot;">​</a></h2><p><strong>Symptom:</strong> Video loop generation spins for a long time and then fails with a 504 Timeout error. <strong>Cause:</strong> The Veo video model is highly resource-intensive and occasionally experiences queuing delays during peak global usage. <strong>Solution:</strong> Your prompt is still queued in the backend. Wait 60 seconds, then click <strong>Generate</strong> again. Often, the result will return instantly on the second try as the backend completes the job.</p><h2 id="_3-select-a-line-message-won-t-disappear" tabindex="-1">3. &quot;Select a line&quot; Message Won&#39;t Disappear <a class="header-anchor" href="#_3-select-a-line-message-won-t-disappear" aria-label="Permalink to &quot;3. &quot;Select a line&quot; Message Won&#39;t Disappear&quot;">​</a></h2><p><strong>Symptom:</strong> You select a scene, but the Visual Stage remains stuck on the &quot;Select a line&quot; placeholder. <strong>Cause:</strong> The Studio UI state may have lost sync with the timeline context, usually after a rapid sequence of scene deletions. <strong>Solution:</strong> Deselect the scene (click outside), then click the scene again. If it persists, refresh the page.</p><h2 id="_4-blurry-or-low-res-images" tabindex="-1">4. Blurry or Low-Res Images <a class="header-anchor" href="#_4-blurry-or-low-res-images" aria-label="Permalink to &quot;4. Blurry or Low-Res Images&quot;">​</a></h2><p><strong>Symptom:</strong> The image in the Visual Stage looks slightly blurry. <strong>Cause:</strong> By default, Sanjeev AI fetches a lower-resolution proxy image for rapid rendering while the high-res master image loads in the background. <strong>Solution:</strong> Wait a few seconds for the high-res image to fully load. Ensure your browser zoom is set to 100%.</p>',9)])])}const p=t(i,[["render",n]]);export{d as __pageData,p as default};
